// Categories per section (tattoo styles, ceramic types, works series…), managed by the client
// in the CMS. src/data/categories.json is generated by scripts/fetch-cms.mjs.
import categoriesData from "../data/categories.json";
import tattoos from "../data/tattoos.json";
import works from "../data/works.json";
import ceramics from "../data/ceramics.json";

export type Lang = "en" | "es";

export interface Category {
	key: string;
	name: Record<Lang, string>;
	description: Record<Lang, string> | null;
	showInFilters: boolean;
}

const all = categoriesData as Record<string, Category[]>;

const splitKeys = (c?: string) => (c ?? "").split(",").map((s) => s.trim()).filter(Boolean);
const usedKeys: Record<string, Set<string>> = {
	tattoos: new Set(tattoos.items.flatMap((i: any) => splitKeys(i.category))),
	ceramics: new Set(ceramics.items.flatMap((i: any) => splitKeys(i.category))),
	works: new Set((works as any[]).map((w) => w.series).filter(Boolean)),
};

/** Categories of a section that have at least one published item, in the client's CMS order. */
export function categoriesWithItems(section: string): Category[] {
	const used = usedKeys[section] ?? new Set();
	return (all[section] ?? []).filter((c) => used.has(c.key));
}

/** Filter buttons for a gallery: "All" + one per category marked "show in filters". */
export function filterButtons(section: string, lang: Lang, allLabel: string) {
	return [
		{ label: allLabel, value: "all", active: true },
		...categoriesWithItems(section)
			.filter((c) => c.showInFilters)
			.map((c) => ({ label: c.name[lang], value: c.key })),
	];
}

/** Display name of a category key, falling back to the key itself. */
export function categoryName(section: string, key: string | undefined, lang: Lang): string {
	if (!key) return "";
	return (all[section] ?? []).find((c) => c.key === key)?.name[lang] ?? key;
}
